import { sql } from 'drizzle-orm';
import { bigint, timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * Column helpers that carry the base rules (docs/01 naming, CLAUDE.md rules 1, 7, 10, 21).
 * Every table is built from these; `conventions.ts` rejects a table that is not.
 */

/** Primary key: UUIDv7 generated by the database (`uuidv7()`, migration 0000). */
export const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

/** A point in time: `timestamptz`, name ends in `_at`, read as a `Date` (UTC). */
export function timestamptz<TName extends `${string}_at`>(name: TName) {
  if (!name.endsWith('_at')) throw new Error(`Timestamp column "${name}" must end in _at`);
  return timestamp(name, { withTimezone: true, mode: 'date' });
}

/**
 * An amount of money in rial: `bigint`, name ends in `_rial`, read as a JS `bigint`
 * (never `number`). Tomans exist only in the UI.
 */
export function rial<TName extends `${string}_rial`>(name: TName) {
  if (!name.endsWith('_rial')) throw new Error(`Money column "${name}" must end in _rial`);
  return bigint(name, { mode: 'bigint' });
}

/**
 * Timestamps of an ordinary table. `updated_at` is maintained by the `set_updated_at()`
 * trigger, which every such table's migration must attach (checked by an integration
 * test). `deleted_at` marks a soft delete: rows are never physically deleted (rule 7).
 */
export const timestamps = () => ({
  createdAt: timestamptz('created_at').notNull().defaultNow(),
  updatedAt: timestamptz('updated_at').notNull().defaultNow(),
  deletedAt: timestamptz('deleted_at'),
});

/**
 * Timestamps of an append-only table (ledger entries, audit events): rows are never
 * updated or deleted, so there is no `updated_at` or `deleted_at`.
 */
export const appendOnlyTimestamps = () => ({
  createdAt: timestamptz('created_at').notNull().defaultNow(),
});
